def move_gate0_files(apps,schema_editor):
    alias=schema_editor.connection.alias
    Activity=apps.get_model('development','Activity')
    Gate0File=apps.get_model('development','Gate0File')
    Food=apps.get_model('development','Food')
    user_app,user_model=settings.AUTH_USER_MODEL.split('.')
    User=apps.get_model(user_app,user_model)
    users=set(User.objects.using(alias).values_list('pk',flat=True))
    sources=Activity.objects.using(alias).filter(
        Q(attachment_stage='gate0')|Q(attachment_slot__in=['G0-F1','G0-F2','G0-F3','G0-F4']),
        food_id__in=Food.objects.using(alias).values('pk'),
    ).exclude(attachment='')
    for activity in sources.iterator():
        if not activity.attachment:continue
        Gate0File.objects.using(alias).create(
            id=activity.pk,development_id=activity.food_id,slot_code=activity.attachment_slot,
            file=str(activity.attachment),original_filename=activity.attachment_name,
            uploader_id=activity.actor_id if activity.actor_id in users else None,
            uploaded_at=activity.created,activity_id=activity.pk,
        )
        Activity.objects.using(alias).filter(pk=activity.pk).update(
            attachment='',attachment_name='',attachment_stage='',attachment_slot='',
        )


def restore_gate0_files(apps,schema_editor):
    alias=schema_editor.connection.alias
    Activity=apps.get_model('development','Activity')
    Gate0File=apps.get_model('development','Gate0File')
    for uploaded in Gate0File.objects.using(alias).all().iterator():
        values={'attachment':str(uploaded.file),'attachment_name':uploaded.original_filename,
                'attachment_stage':'gate0','attachment_slot':uploaded.slot_code}
        if uploaded.activity_id and Activity.objects.using(alias).filter(pk=uploaded.activity_id).exists():
            Activity.objects.using(alias).filter(pk=uploaded.activity_id).update(**values)
        else:
            activity=Activity.objects.using(alias).create(food_id=uploaded.development_id,
                actor_id=uploaded.uploader_id,text='Gate 0 / '+uploaded.slot_code,**values)
            Activity.objects.using(alias).filter(pk=activity.pk).update(created=uploaded.uploaded_at)


